func handleFetch(ctx context.Context, kv *maelstrom.KV, msg maelstrom.Message) error {
    // Parse body
    var body map[string]any
    json.Unmarshal(msg.Body, &body)
    positions := body["positions"].(map[string]any)
    result := make(map[string]any)
    for journalName, posAny := range positions {
        pos := int(posAny.(float64))
        pairs, err := readJournal(ctx, kv, journalName)
        if err != nil {
            return err
        }
        // Filter pairs with pos >= requested position, return some.
        // We can return all, or a subset. Let's return all.
        filtered := make([][]any, 0)
        for _, p := range pairs {
            if p[0] >= pos {
                filtered = append(filtered, []any{float64(p[0]), float64(p[1])})
            }
        }
        if len(filtered) > 0 {
            result[journalName] = filtered
        }
    }
    return n.Reply(msg, map[string]any{
        "type": "fetched",
        "entries": result,
    })
}
